// Test path for the control room event panel: the text arrives as if the order's driver wrote it on Telegram.
// Same route as sim_person: post through the simulated people bot as a reply to Bahn's last message to this driver,
// then hand it to tg_inbound, which links it by that reply and wakes the agent like a real driver message.
const b = $('Report webhook').first().json.body || {}, ref = String(b.order_ref || '').trim().toUpperCase(), text = String(b.text || '').trim().slice(0, 2000);
if (!/^CD-\d+$/.test(ref) || !text) return [{ json: { ok: false, error: 'order_ref and text are required' } }];
const last = $('Last to driver').all().map((r) => r.json).filter((r) => r && r.id && r.tg_message_id).sort((x, y) => y.id - x.id)[0];
if (!last) return [{ json: { ok: false, error: `Bahn has not written to the driver of ${ref} on Telegram yet, so a driver message cannot be linked. Send the event as an alert, or message the driver first.` } }];
const snap = (() => { try { const r = $('Context').first().json; return typeof r.context === 'string' ? JSON.parse(r.context) : (r.context || {}); } catch { return {}; } })();
const name = (snap.assignments || []).find((a) => a.driver)?.driver || 'the driver';
return [{ json: { ok: true, order_ref: ref, text, name, reply_to: String(last.tg_message_id),
  update: { kind: 'message', text, data: '', reply_to_tg_id: String(last.tg_message_id), from_name: `${name} (simulated driver)`, sim: true } } }];
